// What both grammar trainers («Глаголы и предлоги», «Артикли и падежи») share:
// the German determiner tables, the people pronouns in every form a task
// needs, Russian forms that keep a prompt unambiguous, text folding and the
// seeded random the task builders draw with.
//
// Nothing here is generated by a model. Every form a task shows or accepts
// comes out of these tables, so a test can say exactly what is right.

import type { PersonKey, PronounId } from "@/lib/pronouns/catalog";

export type Gender = "m" | "f" | "n" | "pl";
export type Case = "nom" | "acc" | "dat";
export const CASES: Case[] = ["nom", "acc", "dat"];
export const CASE_LABEL: Record<Case, string> = { nom: "Nominativ", acc: "Akkusativ", dat: "Dativ" };
export const GENDER_LABEL: Record<Gender, string> = { m: "мужской", f: "женский", n: "средний", pl: "множественное" };
export const GENDER_ARTICLE: Record<Gender, string> = { m: "der", f: "die", n: "das", pl: "die" };

// ─── Text ────────────────────────────────────────────────────────────────────

/** Spelling-neutral form: case, umlauts as ae/oe/ue, ß as ss. */
export function fold(s: string): string {
  return s.toLowerCase().replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss");
}

export function tokenize(answer: string): string[] {
  return answer.replace(/[.,!?;:«»"„“”()…]/g, " ").split(/\s+/).filter(Boolean);
}

export function levenshtein(a: string, b: string): number {
  if (a === b) return 0;
  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let diag = prev[0];
    prev[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = prev[j];
      prev[j] = Math.min(prev[j] + 1, prev[j - 1] + 1, diag + (a[i - 1] === b[j - 1] ? 0 : 1));
      diag = tmp;
    }
  }
  return prev[b.length];
}

/** One slip in a word long enough that a letter does not make it another word. */
export function nearly(a: string, b: string): boolean {
  if (b.length < 4 || Math.abs(a.length - b.length) > 1) return false;
  const d = levenshtein(a, b);
  if (d === 1) return true;
  // Two neighbouring letters swapped (Shcule) is one slip too.
  if (d === 2 && a.length === b.length) {
    const diff = [...a].map((c, i) => (c === b[i] ? -1 : i)).filter((i) => i >= 0);
    return diff.length === 2 && diff[1] === diff[0] + 1 && a[diff[0]] === b[diff[1]] && a[diff[1]] === b[diff[0]];
  }
  return false;
}

export function cap(s: string): string {
  return s ? s[0].toUpperCase() + s.slice(1) : s;
}

/** Preposition + article fused, as German writes them; checking compares the long form. */
export const CONTRACTIONS: Record<string, [string, string]> = {
  am: ["an", "dem"], zum: ["zu", "dem"], zur: ["zu", "der"], beim: ["bei", "dem"],
  vom: ["von", "dem"], im: ["in", "dem"], ins: ["in", "das"], ans: ["an", "das"],
};

export function contract(prep: string, article: string): string | null {
  for (const [short, [p, a]] of Object.entries(CONTRACTIONS)) {
    // Accusative fusions (ins, ans) are optional in writing; only the dative ones are the norm.
    if (p === prep && a === article && (article === "dem" || (article === "der" && prep === "zu"))) return short;
  }
  return null;
}

// ─── Random, seeded ──────────────────────────────────────────────────────────

export function rng(seed: number): () => number {
  let s = seed >>> 0 || 1;
  return () => {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5; s >>>= 0;
    return s / 0x100000000;
  };
}

export function pickOne<T>(items: T[], random: () => number): T {
  return items[Math.floor(random() * items.length)];
}

export function pickWeighted<T>(items: T[], weights: number[], random: () => number): T {
  const total = weights.reduce((a, b) => a + b, 0);
  let r = random() * total;
  for (let i = 0; i < items.length; i++) {
    r -= weights[i];
    if (r <= 0) return items[i];
  }
  return items[items.length - 1];
}

export function shuffle<T>(items: T[], random: () => number): T[] {
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

export function seedFrom(id: string, n = 0): number {
  let h = 2166136261 ^ n;
  for (let i = 0; i < id.length; i++) h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  return h >>> 0;
}

// ─── Determiners ─────────────────────────────────────────────────────────────

/** der · ein · kein · the possessives, each its own family a task can ask for. */
export const FAMILIES = ["der", "ein", "kein", "mein", "dein", "sein", "ihr", "unser", "euer", "Ihr"] as const;
export type Family = typeof FAMILIES[number];
export const POSSESSIVES: Family[] = ["mein", "dein", "sein", "ihr", "unser", "euer", "Ihr"];

export const FAMILY_LABEL: Record<Family, string> = {
  der: "der / die / das", ein: "ein / eine", kein: "kein / keine",
  mein: "mein (мой)", dein: "dein (твой)", sein: "sein (его)", ihr: "ihr (её, их)",
  unser: "unser (наш)", euer: "euer (ваш)", Ihr: "Ihr (Ваш, вежливо)",
};

const DER: Record<Gender, Record<Case, string>> = {
  m: { nom: "der", acc: "den", dat: "dem" },
  f: { nom: "die", acc: "die", dat: "der" },
  n: { nom: "das", acc: "das", dat: "dem" },
  pl: { nom: "die", acc: "die", dat: "den" },
};

const ENDING: Record<Gender, Record<Case, string>> = {
  m: { nom: "", acc: "en", dat: "em" },
  f: { nom: "e", acc: "e", dat: "er" },
  n: { nom: "", acc: "", dat: "em" },
  pl: { nom: "e", acc: "e", dat: "en" },
};

/** The form, or null where there is none: «ein» has no plural. */
export function determiner(family: Family, gender: Gender, kase: Case): string | null {
  if (family === "der") return DER[gender][kase];
  if (family === "ein" && gender === "pl") return null;
  const ending = ENDING[gender][kase];
  // euer drops its e before an ending: eure, euren, eurem.
  if (family === "euer" && ending) return `eur${ending}`;
  return `${family}${ending}`;
}

export type DeterminerReading = { family: Family; gender: Gender; case: Case };

/** Every (family, gender, case) a written form can be. «sein» the verb is not a determiner here — callers ask about a determiner slot. */
export function readDeterminer(form: string): DeterminerReading[] {
  const f = fold(form);
  const out: DeterminerReading[] = [];
  for (const family of FAMILIES) {
    for (const gender of ["m", "f", "n", "pl"] as Gender[]) {
      for (const kase of CASES) {
        const d = determiner(family, gender, kase);
        if (d && fold(d) === f && !out.some((r) => r.family === family && r.gender === gender && r.case === kase)) out.push({ family, gender, case: kase });
      }
    }
  }
  return out;
}

export function isDeterminer(form: string): boolean {
  return readDeterminer(form).length > 0;
}

/** Every form of one family, in the order the quick keyboard shows them. */
export function familyForms(family: Family): string[] {
  const forms: string[] = [];
  for (const kase of CASES) for (const g of ["m", "f", "n", "pl"] as Gender[]) {
    const d = determiner(family, g, kase);
    if (d && !forms.includes(d)) forms.push(d);
  }
  const order = family === "der" ? ["der", "die", "das", "den", "dem"] : null;
  return order ?? forms.sort((a, b) => a.length - b.length || a.localeCompare(b));
}

// ─── People pronouns ─────────────────────────────────────────────────────────

/** Forms the trainers use; «Sie» stays a subject only — as an object the pronoun trainer covers it. */
export type PersonForms = {
  id: PronounId;
  nom: string; acc: string; dat: string; refl: string;
  de: PersonKey; ru: PersonKey;
  ruNom: string;
  /** Russian object forms after the governing word: «обо мне», «с тобой», «за ним». */
  ruObj: Record<RuGov, string>;
  /** Possessive this person owns, for «свой» checks. */
  owns: Family;
  /** Russian possessive stem when it is not «свой»: мой, твой, его… */
  ruOwn: string;
};

export type RuGov = "acc" | "dat" | "gen" | "ins" | "s_ins" | "o_pre" | "v_pre" | "za_ins" | "u_gen" | "k_dat";

function ruForms(acc: string, dat: string, ins: string, pre: string, gen: string, n: boolean): Record<RuGov, string> {
  // After a preposition он/она/они take н-: с ним, о нём, у неё, к ней.
  const nIns = n ? `н${ins}` : ins;
  const nPre = n ? `н${pre}` : pre;
  const nGen = n ? `н${gen}` : gen;
  const nDat = n ? `н${dat}` : dat;
  const s = ins.startsWith("мн") ? "со" : "с";
  const o = pre.startsWith("мн") ? "обо" : "о";
  const v = pre.startsWith("мн") ? "во" : "в";
  const k = dat.startsWith("мн") ? "ко" : "к";
  return { acc, dat, gen, ins, s_ins: `${s} ${nIns}`, o_pre: `${o} ${nPre}`, v_pre: `${v} ${nPre}`, za_ins: `за ${nIns}`, u_gen: `у ${nGen}`, k_dat: `${k} ${nDat}` };
}

export const PEOPLE: Record<"ich" | "du" | "er" | "sie_sg" | "wir" | "ihr" | "sie_pl" | "Sie", PersonForms> = {
  ich: { id: "ich", nom: "ich", acc: "mich", dat: "mir", refl: "mich", de: "1s", ru: "1s", ruNom: "я", ruObj: ruForms("меня", "мне", "мной", "мне", "меня", false), owns: "mein", ruOwn: "мой" },
  du: { id: "du", nom: "du", acc: "dich", dat: "dir", refl: "dich", de: "2s", ru: "2s", ruNom: "ты", ruObj: ruForms("тебя", "тебе", "тобой", "тебе", "тебя", false), owns: "dein", ruOwn: "твой" },
  er: { id: "er", nom: "er", acc: "ihn", dat: "ihm", refl: "sich", de: "3s", ru: "3s", ruNom: "он", ruObj: ruForms("его", "ему", "им", "ём", "его", true), owns: "sein", ruOwn: "его" },
  sie_sg: { id: "sie_sg", nom: "sie", acc: "sie", dat: "ihr", refl: "sich", de: "3s", ru: "3s", ruNom: "она", ruObj: ruForms("её", "ей", "ей", "ей", "её", true), owns: "ihr", ruOwn: "её" },
  wir: { id: "wir", nom: "wir", acc: "uns", dat: "uns", refl: "uns", de: "1p", ru: "1p", ruNom: "мы", ruObj: ruForms("нас", "нам", "нами", "нас", "нас", false), owns: "unser", ruOwn: "наш" },
  ihr: { id: "ihr", nom: "ihr", acc: "euch", dat: "euch", refl: "euch", de: "2p", ru: "2p", ruNom: "вы", ruObj: ruForms("вас", "вам", "вами", "вас", "вас", false), owns: "euer", ruOwn: "ваш" },
  sie_pl: { id: "sie_pl", nom: "sie", acc: "sie", dat: "ihnen", refl: "sich", de: "3p", ru: "3p", ruNom: "они", ruObj: ruForms("их", "им", "ими", "их", "их", true), owns: "ihr", ruOwn: "их" },
  Sie: { id: "Sie", nom: "Sie", acc: "Sie", dat: "Ihnen", refl: "sich", de: "3p", ru: "2p", ruNom: "Вы", ruObj: ruForms("Вас", "Вам", "Вами", "Вас", "Вас", false), owns: "Ihr", ruOwn: "Ваш" },
};

export type PersonId = keyof typeof PEOPLE;
export const SUBJECTS: PersonId[] = ["ich", "du", "er", "sie_sg", "wir", "ihr", "sie_pl", "Sie"];
/** Objects: no «Sie» (its capital is the pronoun trainer's subject), no «es» (a person is never «es» here). */
export const OBJECTS: PersonId[] = ["ich", "du", "er", "sie_sg", "wir", "ihr", "sie_pl"];

/** Pairs that would need a reflexive or read oddly: «я жду нас», «вы ждёте тебя». */
export function naturalPair(subject: PersonId, object: PersonId): boolean {
  if (subject === object) return false;
  const first: PersonId[] = ["ich", "wir"];
  const second: PersonId[] = ["du", "ihr", "Sie"];
  if (first.includes(subject) && first.includes(object)) return false;
  if (second.includes(subject) && second.includes(object)) return false;
  return true;
}

export function personNotes(subject: PersonId | null, object: PersonId | null, objectRu: string | null): string[] {
  const notes: string[] = [];
  if (subject === "ihr") notes.push("вы — несколько друзей");
  if (subject === "Sie") notes.push("Вы — вежливое обращение");
  if (object === "ihr" && objectRu) notes.push(`${objectRu} — несколько друзей`);
  if (subject === "sie_pl" || object === "sie_pl") { /* «они / их» is unambiguous in Russian */ }
  return notes;
}

/** All pronoun forms any task may show, to recognise a pronoun in an answer. */
export const PRONOUN_FORMS = new Set(["ich", "du", "er", "sie", "es", "wir", "ihr", "mich", "dich", "ihn", "uns", "euch", "mir", "dir", "ihm", "ihnen", "sich"]);

// ─── Russian possessives ─────────────────────────────────────────────────────

type RuCase = "nom" | "acc" | "gen" | "dat" | "ins" | "pre";

/** мой / твой / свой (stem м-, тв-, св-) and наш / ваш, by Russian gender and case. */
export function ruPossessive(stem: string, gender: Gender, kase: RuCase, animate: boolean): string {
  if (stem === "его" || stem === "её" || stem === "их") return stem;
  const hard = stem === "наш" || stem === "ваш" || stem === "Ваш";
  const base = hard ? stem : stem.replace(/ой$/, "");
  if (hard) {
    const t: Record<Gender, Record<RuCase, string>> = {
      m: { nom: "", acc: animate ? "его" : "", gen: "его", dat: "ему", ins: "им", pre: "ем" },
      f: { nom: "а", acc: "у", gen: "ей", dat: "ей", ins: "ей", pre: "ей" },
      n: { nom: "е", acc: "е", gen: "его", dat: "ему", ins: "им", pre: "ем" },
      pl: { nom: "и", acc: animate ? "их" : "и", gen: "их", dat: "им", ins: "ими", pre: "их" },
    };
    return base + t[gender][kase];
  }
  const t: Record<Gender, Record<RuCase, string>> = {
    m: { nom: "ой", acc: animate ? "оего" : "ой", gen: "оего", dat: "оему", ins: "оим", pre: "оём" },
    f: { nom: "оя", acc: "ою", gen: "оей", dat: "оей", ins: "оей", pre: "оей" },
    n: { nom: "оё", acc: "оё", gen: "оего", dat: "оему", ins: "оим", pre: "оём" },
    pl: { nom: "ои", acc: animate ? "оих" : "ои", gen: "оих", dat: "оим", ins: "оими", pre: "оих" },
  };
  return base + t[gender][kase];
}
